-- Lanes follow the tariff: one lane per (origin, destination, mode), served by the origin depot
-- (EU-origin lanes are served by the nearest EU depot).
INSERT INTO lane (origin, destination, mode, depot_code)
SELECT DISTINCT t.origin, t.destination, t.mode,
       CASE substr(t.origin, 1, 2)
            WHEN 'GB' THEN CASE t.origin WHEN 'GBIMM' THEN 'IMM' WHEN 'GBTEE' THEN 'TSB' ELSE 'FXT' END
            WHEN 'NL' THEN 'RTM' WHEN 'BE' THEN 'ANT' WHEN 'DE' THEN 'HAM'
            WHEN 'PL' THEN 'GDY' WHEN 'LT' THEN 'GDY' WHEN 'FI' THEN 'GDY'
            WHEN 'DK' THEN 'HAM' WHEN 'SE' THEN 'HAM' WHEN 'NO' THEN 'IMM'
            ELSE 'RTM' END
  FROM lane_tariff t
ON CONFLICT (origin, destination, mode) DO NOTHING;
